"""Service onboarding pipeline helpers."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class ServiceSpec:
    name: str
    environments: tuple[str, ...] = ("dev", "tst", "rc", "uat", "prd")
    port: int | None = None


def normalize_service_name(name: str) -> str:
    return name.strip().lower().replace("_", "-")


def build_config_repo_name(service_name: str) -> str:
    return f"config-deploy-{normalize_service_name(service_name)}"


def vault_paths(service_name: str, environments: tuple[str, ...]) -> list[str]:
    name = normalize_service_name(service_name)
    return [f"{env}/k8s/{name}" for env in environments]


def create_service(spec: ServiceSpec) -> dict[str, object]:
    name = normalize_service_name(spec.name)
    return {
        "service": name,
        "config_repo": build_config_repo_name(name),
        "environments": list(spec.environments),
        "vault_paths": vault_paths(name, spec.environments),
        "port": spec.port,
    }

